import { loadFont as loadSora } from "@remotion/google-fonts/Sora";
import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// ELYSSON · Andrade Financeira. Motion vertical do empréstimo com limite do cartão (andradefinanceira.com/cartao).
// Pouco material (só o print do simulador): motion. Identidade do site: azul-noite quase preto, dourado em degradê,
// títulos em Sora e interface em Manrope, botões em pílula. O simulador é redesenhado a partir do print do cliente
// (foto-1), com os mesmos valores do print, marcado como "exemplo de simulação".
// Texto entra e fica parado; o movimento contínuo fica no cartão, no celular e nos ícones.
// Tempos = tempos da voz final (src/voz-v1-final.wav, 33,2 s, o locutor); o vídeo tem LEAD de entrada.

const { fontFamily: H } = loadSora("normal", { weights: ["600", "700"], subsets: ["latin", "latin-ext"] });
const { fontFamily: F } = loadManrope("normal", { weights: ["400", "500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const ELY_FPS = 30;
const LEAD = 0.2;
export const ELY_FRAMES = Math.round((LEAD + 35.0) * ELY_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.6));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const BG = "#0A0D12";
const BG2 = "#10141A";
const CARD = "#15181F";
const SEC = "#1D2229";
const GOLD = "#CFAB6D";
const GOLD_L = "#E9CE94";
const GOLD_D = "#C39553";
const FG = "#F5F1EA";
const MUTED = "#9FA5AE";
const GREEN = "#3FC168";
const LINE = "rgba(255,255,255,0.09)";
const GRAD = `linear-gradient(135deg, ${GOLD_L}, ${GOLD_D})`;
const HERO = `radial-gradient(120% 60% at 80% 0%, rgba(207,171,109,0.20), rgba(207,171,109,0) 60%), linear-gradient(180deg, #11151C, ${BG})`;

// trocas de cena
const T2 = 3.5, T3 = 7.55, T4 = 10.15, T5 = 20.55, T6 = 28.65, T7 = 31.55;

const blurIn = (t: number, at: number, out?: number, d = 0.4): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 16 + o * 12).toFixed(1)}px)`,
    transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})`,
  };
};

// linhas de título; a de destaque vem numa pílula dourada
type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; out?: number; hlBg?: string; hlColor?: string }> = ({ t, items, size, top, color = FG, out, hlBg = GRAD, hlColor = BG }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.14 }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: H, fontWeight: 700, fontSize: size, lineHeight: 1.12, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: hl ? hlColor : color, ...(hl ? { background: hlBg, padding: `${size * 0.06}px ${size * 0.32}px ${size * 0.12}px`, borderRadius: size } : {}), ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// ───────── ícones ─────────
type Ico = React.FC<{ s: number; c: string }>;
const sv = (s: number, c: string, ch: React.ReactNode, w = 2) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoCheck: Ico = ({ s, c }) => sv(s, c, <path d="M5 12.5l4.5 4.5L19 7.5" />, 2.6);
const IcoCard: Ico = ({ s, c }) => sv(s, c, <><rect x="2.5" y="5" width="19" height="14" rx="2.5" /><path d="M2.5 10h19M6 15h4" /></>);
const IcoChat: Ico = ({ s, c }) => sv(s, c, <path d="M7.9 20A9 9 0 104 16.1L2 22z" />);
const IcoArrow: Ico = ({ s, c }) => sv(s, c, <path d="M5 12h14M13 6l6 6-6 6" />, 2.4);
const IcoGlobe: Ico = ({ s, c }) => sv(s, c, <><circle cx="12" cy="12" r="9" /><path d="M3 12h18M12 3c2.5 2.6 3.8 5.6 3.8 9s-1.3 6.4-3.8 9c-2.5-2.6-3.8-5.6-3.8-9S9.5 5.6 12 3z" /></>);
const IcoForm: Ico = ({ s, c }) => sv(s, c, <><rect x="4.5" y="3" width="15" height="18" rx="2.5" /><path d="M8.5 8h7M8.5 12h7M8.5 16h4" /></>);
// losango de quatro pétalas (Pix)
const PixMark: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="-50 -50 100 100">
    {[[0, -24], [24, 0], [0, 24], [-24, 0]].map(([x, y], i) => (
      <rect key={i} x={x - 15} y={y - 15} width={30} height={30} rx={7} fill={c} transform={`rotate(45 ${x} ${y})`} />
    ))}
  </svg>
);

const Logo: React.FC<{ w: number; style?: React.CSSProperties }> = ({ w, style }) => (
  <Img src={staticFile("elysson/logo.png")} style={{ width: w, height: w * (95 / 413), ...style }} />
);

// ───────── cartão de crédito desenhado ─────────
const CreditCard: React.FC<{ w: number; fill: number; glow?: number }> = ({ w, fill, glow = 0 }) => {
  const h = w * 0.63, u = w / 100;
  return (
    <div style={{ width: w, height: h, borderRadius: u * 5.5, background: `linear-gradient(140deg, #262B34 0%, #12161C 55%, #0B0E13 100%)`, border: `${u * 0.35}px solid rgba(233,206,148,0.35)`, boxSizing: "border-box", position: "relative", overflow: "hidden", boxShadow: `0 ${u * 8}px ${u * 16}px rgba(0,0,0,0.55), 0 0 ${(u * 10 * glow).toFixed(0)}px rgba(207,171,109,${(0.5 * glow).toFixed(2)})` }}>
      <div style={{ position: "absolute", right: -u * 18, top: -u * 30, width: u * 70, height: u * 70, borderRadius: u * 70, background: "radial-gradient(circle, rgba(233,206,148,0.16), rgba(233,206,148,0) 65%)" }} />
      <Logo w={u * 30} style={{ position: "absolute", left: u * 7, top: u * 7 }} />
      <div style={{ position: "absolute", left: u * 7, top: u * 21, width: u * 13, height: u * 10, borderRadius: u * 2, background: GRAD }}>
        <div style={{ position: "absolute", left: u * 4, top: 0, bottom: 0, width: u * 0.4, background: "rgba(0,0,0,0.25)" }} />
        <div style={{ position: "absolute", left: 0, right: 0, top: u * 4.8, height: u * 0.4, background: "rgba(0,0,0,0.25)" }} />
      </div>
      <div style={{ position: "absolute", left: u * 7, top: u * 36, fontFamily: F, fontWeight: 700, fontSize: u * 5.2, letterSpacing: "0.18em", color: "rgba(245,241,234,0.75)" }}>•••• •••• ••••</div>
      <div style={{ position: "absolute", left: u * 7, right: u * 7, bottom: u * 7 }}>
        <div style={{ fontFamily: F, fontWeight: 700, fontSize: u * 3.4, letterSpacing: "0.14em", color: MUTED }}>LIMITE DISPONÍVEL</div>
        <div style={{ marginTop: u * 2, height: u * 2.6, borderRadius: u * 2, background: "rgba(255,255,255,0.1)", overflow: "hidden" }}>
          <div style={{ width: `${(fill * 100).toFixed(1)}%`, height: "100%", borderRadius: u * 2, background: GRAD }} />
        </div>
      </div>
    </div>
  );
};

// ───────── cena 1 · tem limite? então tem Pix na mão ─────────
const S1: React.FC<{ t: number }> = ({ t }) => {
  const B = 1.86;
  if (t < B) {
    const e = pop(t, -0.15, 0.6);
    return (
      <AbsoluteFill style={{ background: HERO }}>
        <Lines t={t} top={380} size={136} items={[["Tem limite", -0.12]]} />
        <Lines t={t} top={570} size={74} color={GOLD} items={[["no cartão de crédito?", 0.5]]} />
        <div style={{ position: "absolute", left: 540 - 390, top: 940, transformOrigin: "50% 50%", transform: `translate(${((1 - e) * 900).toFixed(1)}px, ${(Math.sin(t * 2.4) * 14).toFixed(1)}px) rotate(${((1 - e) * 28 - 6 + Math.sin(t * 1.8) * 2).toFixed(2)}deg) scale(${(0.95 + 0.08 * lin(t, 0, B) + 0.05 * bump(t, 0.57, 0.4)).toFixed(4)})` }}>
          <CreditCard w={780} fill={0.78 * k(t, 0.57, 0.9)} glow={k(t, 0.57, 0.9)} />
        </div>
      </AbsoluteFill>
    );
  }
  const e = pop(t, 2.55, 0.55);
  const ring = lin(t, 2.6, 3.5);
  return (
    <AbsoluteFill style={{ background: GRAD }}>
      <Lines t={t} top={330} size={88} color={BG} items={[["Então você tem", B + 0.02, false]]} />
      <Lines t={t} top={480} size={150} hlBg={BG} hlColor={GOLD_L} items={[["Pix na mão.", 2.57, true]]} />
      <div style={{ position: "absolute", left: 540, top: 1180, width: 0, height: 0 }}>
        <div style={{ position: "absolute", width: 420 + ring * 900, height: 420 + ring * 900, borderRadius: 3000, border: `${(10 * (1 - ring)).toFixed(1)}px solid ${BG}`, transform: "translate(-50%, -50%)", opacity: 0.35 * (1 - ring) }} />
        <div style={{ position: "absolute", left: -210, top: -210, width: 420, height: 420, borderRadius: 420, background: BG, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: "0 40px 80px rgba(60,40,10,0.35)", transform: `translateY(${(Math.sin(t * 3) * 12).toFixed(1)}px) scale(${(e * (1 + 0.04 * Math.sin(t * 4))).toFixed(4)}) rotate(${((1 - e) * -90 + Math.sin(t * 2.2) * 6).toFixed(1)}deg)` }}>
          <PixMark s={220} c={GOLD_L} />
        </div>
      </div>
      {/* a mão segurando: o cartão pequeno entra por baixo e encosta no Pix */}
      <div style={{ position: "absolute", left: 540 - 170, top: 1470, transform: `translateY(${((1 - k(t, B + 0.1, 0.6)) * 600 + Math.sin(t * 2.6) * 10).toFixed(1)}px) rotate(${(-8 + Math.sin(t * 2) * 2).toFixed(2)}deg)` }}>
        <CreditCard w={340} fill={0.78} />
      </div>
    </AbsoluteFill>
  );
};

// ───────── cena 2 · o limite vira dinheiro na conta ─────────
const PixNotice: React.FC<{ w: number; title: string; sub: string }> = ({ w, title, sub }) => (
  <div style={{ width: w, borderRadius: 44, background: CARD, border: `2px solid ${LINE}`, boxSizing: "border-box", padding: "34px 40px", display: "flex", alignItems: "center", gap: 30, boxShadow: "0 30px 70px rgba(0,0,0,0.5)" }}>
    <div style={{ width: 120, height: 120, borderRadius: 120, background: GRAD, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><PixMark s={70} c={BG} /></div>
    <div style={{ flex: 1 }}>
      <div style={{ fontFamily: H, fontWeight: 700, fontSize: 50, color: FG, letterSpacing: "-0.03em" }}>{title}</div>
      <div style={{ fontFamily: F, fontWeight: 500, fontSize: 34, color: MUTED, marginTop: 6 }}>{sub}</div>
    </div>
    <div style={{ width: 76, height: 76, borderRadius: 76, background: "rgba(63,193,104,0.16)", display: "flex", alignItems: "center", justifyContent: "center" }}><IcoCheck s={46} c={GREEN} /></div>
  </div>
);
const S2: React.FC<{ t: number }> = ({ t }) => {
  const ce = pop(t, T2 + 0.15, 0.6);
  const flow = io(t, 6.0, 6.75);
  const ne = pop(t, 6.8, 0.55);
  return (
    <AbsoluteFill style={{ background: HERO }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: 180, display: "flex", justifyContent: "center", ...blurIn(t, 3.6, undefined, 0.5) }}><Logo w={460} /></div>
      <Lines t={t} top={400} size={74} items={[["O limite do seu cartão", 4.83]]} />
      <Lines t={t} top={520} size={104} items={[["vira dinheiro", 6.03, true]]} />
      <Lines t={t} top={686} size={74} items={[["na sua conta.", 6.83]]} />
      <div style={{ position: "absolute", inset: 0, transformOrigin: "540px 1250px", transform: `scale(${(0.94 + 0.09 * lin(t, T2, T3)).toFixed(4)})` }}>
        <div style={{ position: "absolute", left: 540 - 300, top: 900, transform: `translateY(${((1 - ce) * 700 + Math.sin(t * 2.4) * 12).toFixed(1)}px) rotate(${((1 - ce) * -20 + Math.sin(t * 1.7) * 2).toFixed(2)}deg) scale(${(1 - 0.08 * flow + 0.05 * bump(t, 6.03, 0.4)).toFixed(4)})` }}>
          <CreditCard w={600} fill={0.78 - 0.5 * flow} glow={flow} />
        </div>
        {/* o valor descendo do cartão para a conta */}
        {[0, 1, 2, 3].map((i) => {
          const p = lin(t, 6.0 + i * 0.12, 6.75 + i * 0.12);
          return p > 0 && p < 1 ? (
            <div key={i} style={{ position: "absolute", left: 540 - 22 + (i % 2 ? 40 : -40), top: 1240 + p * 230, width: 44, height: 44, transform: `rotate(45deg) scale(${(1 - p * 0.4).toFixed(3)})`, borderRadius: 10, background: GRAD, opacity: 1 - p * 0.6 }} />
          ) : null;
        })}
        <div style={{ position: "absolute", left: 110, top: 1500, opacity: Math.min(1, ne * 2), transform: `translateY(${((1 - ne) * 160 + Math.sin(t * 2.6 + 1) * 8).toFixed(1)}px) scale(${(0.85 + 0.15 * ne).toFixed(4)})` }}>
          <PixNotice w={860} title="Pix recebido" sub="Andrade Financeira · agora" />
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── cena 3 · paga parcelado na fatura ─────────
const S3: React.FC<{ t: number }> = ({ t }) => {
  const rows: [string, string, number][] = [["Pagamento", "Na fatura", 8.0], ["Parcelas", "1x a 12x", 8.5], ["Recebe", "Pix na conta", 9.17]];
  const ce = pop(t, T3 + 0.1, 0.6);
  return (
    <AbsoluteFill style={{ background: BG2 }}>
      <Lines t={t} top={380} size={92} items={[["E paga parcelado", 7.64]]} />
      <Lines t={t} top={520} size={100} items={[["na fatura", 9.15, true]]} />
      <div style={{ position: "absolute", left: 120, top: 820, width: 840, opacity: Math.min(1, ce * 2), transformOrigin: "50% 40%", transform: `translateY(${((1 - ce) * 500 + Math.sin(t * 2.2) * 12).toFixed(1)}px) rotate(${((1 - ce) * 8 + Math.sin(t * 1.6) * 1.2).toFixed(2)}deg) scale(${(0.96 + 0.06 * lin(t, T3, T4)).toFixed(4)})` }}>
        <div style={{ borderRadius: 52, background: CARD, border: `2px solid ${LINE}`, padding: "52px 56px 30px", boxSizing: "border-box", boxShadow: "0 40px 90px rgba(0,0,0,0.5)" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 26, marginBottom: 26 }}>
            <div style={{ width: 96, height: 96, borderRadius: 28, background: "rgba(207,171,109,0.14)", display: "flex", alignItems: "center", justifyContent: "center" }}><IcoCard s={58} c={GOLD} /></div>
            <div style={{ fontFamily: H, fontWeight: 700, fontSize: 56, color: FG, letterSpacing: "-0.03em" }}>Limite do cartão</div>
          </div>
          {rows.map(([a, b, at], i) => {
            const e = pop(t, at, 0.45);
            return (
              <div key={a} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderTop: `2px solid ${LINE}`, padding: "46px 0", fontFamily: F, opacity: 0.25 + 0.75 * Math.min(1, e * 2), transform: `translateX(${((1 - e) * (i % 2 ? 60 : -60)).toFixed(1)}px)` }}>
                <span style={{ fontWeight: 500, fontSize: 44, color: MUTED }}>{a}</span>
                <span style={{ fontWeight: 800, fontSize: 50, color: i === 2 ? GOLD_L : FG, transform: `scale(${(1 + 0.08 * bump(t, at, 0.4)).toFixed(3)})` }}>{b}</span>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── cena 4 · como simular: o simulador do site, passo a passo ─────────
const brl = (v: number, dec = 2) => v.toLocaleString("pt-BR", { minimumFractionDigits: dec, maximumFractionDigits: dec });
const SimScreen: React.FC<{ u: number; t: number }> = ({ u, t }) => {
  const tog = io(t, 12.5, 12.85);
  const val = k(t, 13.85, 0.9);
  const lim = 150 + (1000 - 150) * val;
  const sel = bump(t, 14.85, 0.45);
  const res = k(t, 16.0, 1.2);
  const btn = bump(t, 17.3, 0.45);
  const lab = (top: number, txt: string): React.ReactNode => <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * top, fontFamily: F, fontWeight: 600, fontSize: u * 4.1, color: FG }}>{txt}</div>;
  return (
    <div style={{ position: "absolute", inset: 0, background: BG2, fontFamily: F }}>
      <div style={{ position: "absolute", left: 0, right: 0, top: u * 14, textAlign: "center", fontWeight: 500, fontSize: u * 3.6, color: MUTED }}>Etapa 1 de 5 · Simulação</div>
      <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * 22, display: "flex", gap: u * 1.6 }}>
        {[0, 1, 2, 3, 4].map((i) => <div key={i} style={{ flex: 1, height: u * 1, borderRadius: u, background: i === 0 ? GOLD : "rgba(255,255,255,0.12)" }} />)}
      </div>
      <div style={{ position: "absolute", left: u * 6, top: u * 31, fontFamily: H, fontWeight: 700, fontSize: u * 7, color: FG, letterSpacing: "-0.03em" }}>Simule seu Pix</div>
      <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * 41, fontWeight: 400, fontSize: u * 3.7, color: MUTED }}>Em poucos segundos você vê quanto vai receber.</div>
      {/* alternância */}
      <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * 50, height: u * 12, borderRadius: u * 6, background: SEC }}>
        <div style={{ position: "absolute", top: u * 1, bottom: u * 1, width: "49%", left: `${(1 + tog * 50).toFixed(1)}%`, borderRadius: u * 5, background: GRAD, transform: `scale(${(1 + 0.05 * bump(t, 12.7, 0.35)).toFixed(3)})` }} />
        {["Quero um valor", "Usar meu limite"].map((s, i) => (
          <div key={s} style={{ position: "absolute", top: 0, bottom: 0, left: i ? "50%" : 0, width: "50%", display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 600, fontSize: u * 3.7, color: (i ? tog > 0.5 : tog <= 0.5) ? BG : MUTED }}>{s}</div>
        ))}
      </div>
      {lab(68, "Qual o limite disponível no seu cartão?")}
      <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * 76, height: u * 16, borderRadius: u * 8, background: BG, border: `${u * 0.3}px solid ${val > 0 && val < 1 ? GOLD : LINE}`, display: "flex", alignItems: "center", padding: `0 ${u * 5}px`, gap: u * 2, fontWeight: 800 }}>
        <span style={{ fontSize: u * 5.6, color: MUTED }}>R$</span>
        <span style={{ fontSize: u * 7.6, color: FG, letterSpacing: "-0.02em" }}>{brl(Math.round(lim / 10) * 10, 0)}</span>
      </div>
      <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * 99, height: u * 1.6, borderRadius: u, background: "rgba(255,255,255,0.85)" }}>
        <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: `${(4 * val + 0.5).toFixed(2)}%`, borderRadius: u, background: GOLD }} />
        <div style={{ position: "absolute", left: `${(4 * val).toFixed(2)}%`, top: -u * 2.2, width: u * 8, height: u * 6, borderRadius: u * 3, background: "#FFF", boxShadow: "0 2px 6px rgba(0,0,0,0.4)", transform: `scale(${(1 + 0.25 * bump(t, 13.85, 0.5)).toFixed(3)})` }} />
      </div>
      <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * 104, display: "flex", justifyContent: "space-between", fontWeight: 500, fontSize: u * 3.1, color: MUTED }}><span>R$ 150</span><span>R$ 20.000</span></div>
      {lab(114, "Em quantas vezes quer pagar?")}
      <div style={{ position: "absolute", left: u * 6, right: u * 6, top: u * 122, height: u * 14, borderRadius: u * 7, background: BG, border: `${u * 0.3}px solid ${sel > 0.05 ? GOLD : LINE}`, display: "flex", alignItems: "center", justifyContent: "space-between", padding: `0 ${u * 5}px`, fontWeight: 600, fontSize: u * 4.4, color: FG, transform: `scale(${(1 + 0.04 * sel).toFixed(3)})` }}>
        <span>12 parcelas mensais</span><span style={{ color: MUTED, fontSize: u * 3.4 }}>⌄</span>
      </div>
      <div style={{ position: "absolute", left: u * 6, top: u * 139, fontWeight: 500, fontSize: u * 3.6, color: MUTED, opacity: lin(t, 14.9, 15.2) }}>12x de R$ 83,33 na fatura do cartão</div>
      {/* resultado */}
